import { BARD_SPELL_LIBRARY } from "./bard-spells.generated.js";
import { EXTRA_SPELLS } from "./extra-spells.js";

function assertNoDuplicateSpellIds(spells) {
  const ids = new Set();

  for (const spell of spells) {
    if (ids.has(spell.id)) {
      throw new Error(`Duplicate spell ID: ${spell.id}`);
    }

    ids.add(spell.id);
  }
}

export const SPELL_LIBRARY = [
  ...BARD_SPELL_LIBRARY,
  ...EXTRA_SPELLS,
];

assertNoDuplicateSpellIds(SPELL_LIBRARY);

const canonicalSpellLibraryById = Object.fromEntries(
  SPELL_LIBRARY.map((spell) => [spell.id, spell]),
);

export const SPELL_LIBRARY_BY_ID = {
  ...canonicalSpellLibraryById,
};

import { getDerivedStats } from "./calculations.js";
import {
  clamp,
  ensureCombatState,
  ensureEffectsState,
  ensureInventoryState,
  ensureRulesOverridesState,
  ensureSpellcastingState,
  ensureTurnState,
  ensureUiState,
  ensureSpellsUiState,
  ensureMeleeUiState,
  ensureInventoryUiState,
} from "./state-helpers.js";
import {
  isCantripSelected,
  isPreparedSpellSelected,
  isGrantedSpell,
} from "./selectors/spellcasting.js";
import {
  getBardCantripLimit,
  getBardPreparedSpellLimit,
  SKILL_ID_META,
} from "./rules.js";
import { buildCharacterSpellCollections, BARD_SPELL_LIBRARY_BY_ID } from "./selectors/spellcasting.js";


export const STATELESS_ACTIONS = new Set(["print-sheet", "reset-runtime"]);

function buildRuntimeId(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function toRuntimeSlug(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replaceAll("’", "'")
    .replace(/[^a-zа-яё0-9]+/gi, "-")
    .replace(/^-+|-+$/g, "");
}

function getMaxHp(derived) {
  return Number(derived.maxHitPoints ?? derived.maxHp ?? 0);
}

function resolveLibrarySpellById(spellId) {
  if (!spellId) {
    return null;
  }

  const normalizedId = String(spellId);

  return (
    BARD_SPELL_LIBRARY_BY_ID[normalizedId]
    ?? BARD_SPELL_LIBRARY_BY_ID[`${normalizedId}-2014`]
    ?? BARD_SPELL_LIBRARY_BY_ID[`${normalizedId}-2024`]
    ?? null
  );
}

function findSpellByActionId(spells, spellId) {
  return spells.find((entry) => String(entry.id) === String(spellId));
}

function spendSpellSlotIfAvailable(draft, spellLevel) {
  if (spellLevel <= 0) {
    return true;
  }

  const spellcasting = ensureSpellcastingState(draft);
  const derived = getDerivedStats(draft);
  const slotState = (derived.spellSlots || []).find(
    (slot) => Number(slot.level) === Number(spellLevel)
  );

  if (!slotState || Number(slotState.available) <= 0) {
    return false;
  }

  const used = Number(spellcasting.slotsUsed[spellLevel] || 0);
  spellcasting.slotsUsed[spellLevel] = used + 1;
  return true;
}

function markTurnConsumption(draft, castTime) {
  const turn = ensureTurnState(draft);

  if (String(castTime || "").toLowerCase().includes("бонусное действие")) {
    turn.bonusActionUsed = true;
    return;
  }

  turn.actionUsed = true;
}

function handleHpChange(draft, target) {
  const delta = Number(target.dataset.delta || 0);
  const combat = ensureCombatState(draft);
  const derived = getDerivedStats(draft);
  const nextValue = Number(combat.hp.current || 0) + delta;

  combat.hp.current = clamp(nextValue, 0, getMaxHp(derived));
}

function handleHpReset(draft) {
  const combat = ensureCombatState(draft);
  const derived = getDerivedStats(draft);

  combat.hp.current = getMaxHp(derived);
  combat.hp.temp = 0;
}

function handleToggleAbilitiesEdit(draft) {
  const ui = ensureUiState(draft);
  ui.abilitiesEditable = !Boolean(ui.abilitiesEditable);
}

function handleInventoryAddItem(draft) {
  const inventory = ensureInventoryState(draft);

  inventory.items.push({
    id: buildRuntimeId("item"),
    type: "misc",
    name: "",
    quantity: 1,
    stackable: false,
    equipped: false,
    notes: "",
    tags: [],
    weapon: null,
    armor: null,
    focus: null,
    consumable: null,
    uses: null,
    charges: null,
  });
}

function handleInventoryRemoveItem(draft, target) {
  const itemId = target.dataset.itemId;
  const inventory = ensureInventoryState(draft);

  inventory.items = inventory.items.filter((item) => item.id !== itemId);
}

function handleLongRest(draft) {
  const combat = ensureCombatState(draft);
  const turn = ensureTurnState(draft);
  const spellcasting = ensureSpellcastingState(draft);
  const effects = ensureEffectsState(draft);
  const derived = getDerivedStats(draft);

  turn.actionUsed = false;
  turn.bonusActionUsed = false;
  turn.reactionUsed = false;
  turn.turnNumber = 1;

  if (draft.spellcasting?.spellOverrides && typeof draft.spellcasting.spellOverrides === "object") {
    Object.values(draft.spellcasting.spellOverrides).forEach((spell) => {
      if (spell?.uses?.max != null) {
        spell.uses.current = Number(spell.uses.max || 0);
      }
    });
  }

  combat.hp.current = getMaxHp(derived);
  combat.hp.temp = 0;
  const bardic = combat.bardicInspiration;
  if (bardic) {
    bardic.current = Number(derived.bardicInspiration?.max || 0);
    }
  combat.concentration = "";

  const nextSlotsUsed = {};
  for (const slot of derived.spellSlots || []) {
    nextSlotsUsed[slot.level] = 0;
  }
  spellcasting.slotsUsed = nextSlotsUsed;

  effects.length = 0;
}

function handleResetRuntime(resetState) {
  resetState();
}

function handleShortRest(draft) {
  const combat = ensureCombatState(draft);
  const turn = ensureTurnState(draft);
  const effects = ensureEffectsState(draft);

  turn.actionUsed = false;
  turn.bonusActionUsed = false;
  turn.reactionUsed = false;

  combat.hp.temp = 0;
  combat.concentration = "";

  const retained = effects.filter((effect) => effect.durationType !== "until-short-rest");
  effects.length = 0;
  effects.push(...retained);
}

function handleConcentrationClear(draft) {
  const combat = ensureCombatState(draft);
  combat.concentration = "";
}

function handleEffectAdd(draft) {
  const effects = ensureEffectsState(draft);
  const combat = ensureCombatState(draft);

  effects.push({
    id: buildRuntimeId("effect"),
    name: "Новый эффект",
    source: combat.concentration || "Ручной эффект",
    duration: "До конца сцены",
    durationType: "custom",
    notes: "",
  });
}

function handleEffectRemove(draft, target) {
  const effectId = target.dataset.effectId;
  const effects = ensureEffectsState(draft);
  const retained = effects.filter((effect) => effect.id !== effectId);

  effects.length = 0;
  effects.push(...retained);
}

function handleAbilityAdjust(draft, target) {
  const abilityId = target.dataset.abilityId;
  const delta = Number(target.dataset.delta || 0);

  if (!abilityId || typeof draft.abilities?.[abilityId] !== "number") {
    return;
  }

  draft.abilities[abilityId] = clamp((draft.abilities[abilityId] || 0) + delta, 8, 30);
}

function handleSkillToggle(draft, target) {
  const skillId = String(target.dataset.skillId ?? "");
  const toggle = String(target.dataset.toggle ?? "");

  if (!skillId || !toggle) {
    return;
  }

  if (!Array.isArray(draft.skills)) {
    draft.skills = [];
  }

  let skill = draft.skills.find((entry) => entry.id === skillId);

  if (!skill) {
    const meta = SKILL_ID_META[skillId];
    if (!meta) {
      return;
    }

    skill = {
      id: skillId,
      name: meta.label,
      ability: meta.ability,
      proficient: false,
      expertise: false,
      source: null,
    };
    draft.skills.push(skill);
  }

  if (toggle === "proficient") {
    const nextProficient = !Boolean(skill.proficient);
    skill.proficient = nextProficient;

    if (!nextProficient) {
      skill.expertise = false;
    }
    return;
  }

  if (toggle === "expertise") {
    const nextExpertise = !Boolean(skill.expertise);
    skill.expertise = nextExpertise;

    if (nextExpertise) {
      skill.proficient = true;
    }
  }
}

function handleSavingThrowToggle(draft, target) {
  const abilityId = String(target.dataset.abilityId ?? "");

  if (!abilityId) {
    return;
  }

  if (!draft.savingThrows || typeof draft.savingThrows !== "object") {
    draft.savingThrows = {};
  }

  if (
    !draft.savingThrows[abilityId] ||
    typeof draft.savingThrows[abilityId] !== "object"
  ) {
    draft.savingThrows[abilityId] = {
      proficient: false,
    };
  }

  draft.savingThrows[abilityId].proficient = !Boolean(
    draft.savingThrows[abilityId].proficient
  );
}

function handleHpApplyDamage(draft) {
  const combat = ensureCombatState(draft);
  const derived = getDerivedStats(draft);
  const maxHp = getMaxHp(derived);
  const amount = Math.max(0, Number(draft.ui?.hpAdjustAmount || 0));

  const currentTemp = Number(combat.hp.temp || 0);
  const currentHp = Number(combat.hp.current || 0);

  const tempAbsorbed = Math.min(currentTemp, amount);
  const remainingDamage = amount - tempAbsorbed;

  combat.hp.temp = currentTemp - tempAbsorbed;
  combat.hp.current = clamp(currentHp - remainingDamage, 0, maxHp);
}

function handleHpApplyHeal(draft) {
  const combat = ensureCombatState(draft);
  const derived = getDerivedStats(draft);
  const maxHp = getMaxHp(derived);
  const amount = Math.max(0, Number(draft.ui?.hpAdjustAmount || 0));
  const currentHp = Number(combat.hp.current || 0);

  combat.hp.current = clamp(currentHp + amount, 0, maxHp);
}

function handleSlotSetUsed(draft, target) {
  const slotLevel = Number(target.dataset.slotLevel);
  const slotIndex = Number(target.dataset.slotIndex);

  if (Number.isNaN(slotLevel) || Number.isNaN(slotIndex)) {
    return;
  }

  const spellcasting = ensureSpellcastingState(draft);
  const derived = getDerivedStats(draft);
  const slotState = (derived.spellSlots || []).find(
    (slot) => Number(slot.level) === slotLevel
  );

  if (!slotState) {
    return;
  }

  const max = Number(slotState.max || 0);
  const currentAvailable = Number(slotState.available || 0);
  const nextAvailable = currentAvailable === slotIndex ? slotIndex - 1 : slotIndex;

  spellcasting.slotsUsed[slotLevel] = clamp(max - nextAvailable, 0, max);
}

function handleBardicSetCurrent(draft, target) {
  const chargeIndex = Number(target.dataset.chargeIndex);
  const combat = ensureCombatState(draft);
  const bardic = combat.bardicInspiration;

  if (!bardic || Number.isNaN(chargeIndex)) {
    return;
  }

  const derived = getDerivedStats(draft);
  const max = Number(derived.bardicInspiration?.max || 0);
  const current = Number(bardic.current || 0);
  const nextCurrent = current === chargeIndex ? chargeIndex - 1 : chargeIndex;

  bardic.current = clamp(nextCurrent, 0, max);
}

function handleTurnToggleAction(draft) {
  const turn = ensureTurnState(draft);
  turn.actionUsed = !Boolean(turn.actionUsed);
}

function handleTurnToggleBonusAction(draft) {
  const turn = ensureTurnState(draft);
  turn.bonusActionUsed = !Boolean(turn.bonusActionUsed);
}

function handleTurnToggleReaction(draft) {
  const turn = ensureTurnState(draft);
  turn.reactionUsed = !Boolean(turn.reactionUsed);
}

function handleTurnEnd(draft) {
  const turn = ensureTurnState(draft);
  turn.actionUsed = false;
  turn.bonusActionUsed = false;
  turn.reactionUsed = false;
  turn.turnNumber = Number(turn.turnNumber || 1) + 1;
}

function handleBardicUse(draft, target) {
  const markBonusAction = target.dataset.markBonusAction !== "false";
  const combat = ensureCombatState(draft);
  const bardic = combat.bardicInspiration;

  if (!bardic) {
    return;
  }

  const derived = getDerivedStats(draft);
  const max = Number(derived.bardicInspiration?.max || 0);
  const current = clamp(Number(bardic.current || 0), 0, max);

  if (current <= 0) {
    return;
  }

  bardic.current = current - 1;

  if (markBonusAction) {
    const turn = ensureTurnState(draft);
    turn.bonusActionUsed = true;
  }
}

function handleWeaponAttack(draft) {
  const turn = ensureTurnState(draft);
  turn.actionUsed = true;
}

function handleSpellCast(draft, target) {
  const spellId = target.dataset.spellId;
  const spellLevel = Number(target.dataset.spellLevel || 0);
  const castTime = String(target.dataset.castTime || "").toLowerCase();
  const setsConcentration = target.dataset.setsConcentration === "true";

  if (!spellId) {
    return;
  }

  const collections = buildCharacterSpellCollections(draft);
  const allAvailableSpells = [
    ...collections.cantrips,
    ...collections.preparedSpells,
    ...collections.grantedSpells,
  ];

  const spell = findSpellByActionId(allAvailableSpells, spellId);

  if (!spell) {
    return;
  }

  if (spell.uses?.max != null) {
    const currentUses = Number(spell.uses.current || 0);

    if (currentUses > 0) {
      const spellcasting = ensureSpellcastingState(draft);
      if (!spellcasting.spellOverrides || typeof spellcasting.spellOverrides !== "object") {
        spellcasting.spellOverrides = {};
      }

      const currentOverride = spellcasting.spellOverrides[spell.id] ?? {};
      spellcasting.spellOverrides[spell.id] = {
        ...currentOverride,
        uses: {
          ...(currentOverride.uses ?? spell.uses),
          current: currentUses - 1,
          max: Number(spell.uses.max || 0),
          refresh: spell.uses.refresh,
        },
      };
    } else if (!spendSpellSlotIfAvailable(draft, spellLevel)) {
      return;
    }
  } else if (!spendSpellSlotIfAvailable(draft, spellLevel)) {
    return;
  }

  markTurnConsumption(draft, castTime);

  const combat = ensureCombatState(draft);
  if (setsConcentration) {
    combat.concentration = spell.name || "";
  }
}

function handleToggleJackOfAllTrades(draft) {
  const rulesOverrides = ensureRulesOverridesState(draft);
  rulesOverrides.disableJackOfAllTrades = !Boolean(
    rulesOverrides.disableJackOfAllTrades
  );
}

function handleToggleDuelingStyle(draft) {
  const rulesOverrides = ensureRulesOverridesState(draft);
  rulesOverrides.disableDuelingStyle = !Boolean(rulesOverrides.disableDuelingStyle);
}

function handlePrintSheet() {
  window.print();
}

function normalizeLevelDependentState(draft) {
  const derived = getDerivedStats(draft);
  const combat = ensureCombatState(draft);
  const spellcasting = ensureSpellcastingState(draft);

  combat.hp.current = clamp(Number(combat.hp.current || 0), 0, getMaxHp(derived));

  const normalizedSlotsUsed = {};
  for (const slot of derived.spellSlots || []) {
    const max = Number(slot.max || 0);
    const used = Number(spellcasting.slotsUsed?.[slot.level] || 0);
    normalizedSlotsUsed[slot.level] = clamp(used, 0, max);
  }
  spellcasting.slotsUsed = normalizedSlotsUsed;

  const bardic = combat.bardicInspiration;
  if (bardic) {
    const maxBardic = Number(derived.bardicInspiration?.max || 0);
    bardic.current = clamp(Number(bardic.current || 0), 0, maxBardic);
  }
}

function handleLevelAdjust(draft, target) {
  const delta = Number(target.dataset.delta || 0);

  if (!Number.isFinite(delta) || delta === 0) {
    return;
  }

  if (!draft.profile || typeof draft.profile !== "object") {
    draft.profile = {};
  }

  const currentLevel = Math.max(1, Number(draft.profile.level || 1));
  const nextLevel = clamp(currentLevel + delta, 1, 20);

  if (nextLevel === currentLevel) {
    return;
  }

  draft.profile.level = nextLevel;
  normalizeLevelDependentState(draft);
}

function handleSpellLibrarySetLevel(draft, target) {
  const levelValue = target.dataset.spellLibraryLevel;
  const ui = ensureUiState(draft);

  ui.spellLibrary.selectedLevel = levelValue ?? "all";
}

function handleSpellLibraryToggleExpand(draft, target) {
  const spellId = target.dataset.spellLibraryToggle;

  if (!spellId) {
    return;
  }

  const ui = ensureUiState(draft);
  const expandedSpellIds = ui.spellLibrary.expandedSpellIds;
  const alreadyExpanded = expandedSpellIds.includes(spellId);

  ui.spellLibrary.expandedSpellIds = alreadyExpanded
    ? expandedSpellIds.filter((id) => id !== spellId)
    : [...expandedSpellIds, spellId];
}

function handleSpellLibraryToggleSelect(draft, target) {
  const rawSpellId = target.dataset.spellLibrarySelect;
  const mode = target.dataset.spellLibraryMode;
  const level = Number(draft.profile?.level ?? 1);
  const spellcasting = ensureSpellcastingState(draft);

  if (!rawSpellId || !mode) {
    return;
  }

  const resolvedSpell = resolveLibrarySpellById(rawSpellId);
  if (!resolvedSpell) {
    console.warn("[actions] Unknown library spell id:", rawSpellId);
    return;
  }

  const spellId = resolvedSpell.id;

  if (
    resolvedSpell.availableFromLevel &&
    Number(resolvedSpell.availableFromLevel) > level
  ) {
    return;
  }

  if (isGrantedSpell(draft, spellId)) {
    return;
  }

  if (!Array.isArray(spellcasting.cantripIds)) {
    spellcasting.cantripIds = [];
  }

  if (!Array.isArray(spellcasting.preparedSpellIds)) {
    spellcasting.preparedSpellIds = [];
  }

  const cantripIds = [...new Set(spellcasting.cantripIds.filter(Boolean))];
  const preparedSpellIds = [...new Set(spellcasting.preparedSpellIds.filter(Boolean))];

  if (mode === "cantrip") {
    const grantedSpellIdSet = new Set(
      Array.isArray(spellcasting.grantedSpellIds)
        ? spellcasting.grantedSpellIds.filter(Boolean)
        : [],
    );

    const selected = cantripIds.includes(spellId);
    const classCantripIds = cantripIds.filter((id) => !grantedSpellIdSet.has(id));

    if (grantedSpellIdSet.has(spellId)) {
      return;
    }

    if (selected) {
      spellcasting.cantripIds = cantripIds.filter((id) => id !== spellId);
      return;
    }

    const limit = getBardCantripLimit(level);
    if (classCantripIds.length >= limit) {
      return;
    }

    spellcasting.cantripIds = [...cantripIds, spellId];
    return;
  }

  if (mode === "prepared") {
    const selected = preparedSpellIds.includes(spellId);

    if (selected) {
      spellcasting.preparedSpellIds = preparedSpellIds.filter((id) => id !== spellId);
      return;
    }

    const limit = getBardPreparedSpellLimit(level);
    if (preparedSpellIds.length >= limit) {
      return;
    }

    spellcasting.preparedSpellIds = [...preparedSpellIds, spellId];
  }
}

function handleSpellLibrarySetSelectionFilter(draft, target) {
  const selectionValue = String(
    target.dataset.spellLibrarySelection ?? "all",
  );

  const ui = ensureUiState(draft);
  const currentValue = ui.spellLibrary.selectionFilter;

  ui.spellLibrary.selectionFilter = (
    currentValue === selectionValue
      ? "all"
      : selectionValue
  );
}

function handleSpellLibrarySearch(draft, target) {
  const ui = ensureUiState(draft);

  ui.spellLibrary.searchQuery = String(target.value ?? "");
}

function handleSpellLibrarySetSchool(draft, target) {
  const ui = ensureUiState(draft);

  ui.spellLibrary.schoolFilter = String(
    target.dataset.spellLibrarySchool ?? "all",
  );
}

function handleSpellLibraryToggleFlag(draft, target) {
  const flag = String(target.dataset.spellLibraryFlag ?? "");

  const allowedFlags = new Set([
    "concentrationOnly",
    "ritualOnly",
    "availableOnly",
  ]);

  if (!allowedFlags.has(flag)) {
    return;
  }

  const ui = ensureUiState(draft);

  ui.spellLibrary[flag] = !ui.spellLibrary[flag];
}

function handleSpellsToggleExpand(draft, target) {
  const spellId = target.dataset.spellsToggle;
  if (!spellId) return;

  const spellsUi = ensureSpellsUiState(draft);
  const expandedSpellIds = Array.isArray(spellsUi.expandedSpellIds)
    ? spellsUi.expandedSpellIds
    : [];

  const alreadyExpanded = expandedSpellIds.includes(spellId);

  spellsUi.expandedSpellIds = alreadyExpanded
    ? expandedSpellIds.filter((id) => id !== spellId)
    : [...expandedSpellIds, spellId];
}

function handleMeleeToggleExpand(draft, target) {
  const cardId = target.dataset.meleeToggle;
  if (!cardId) return;

  const meleeUi = ensureMeleeUiState(draft);
  const expandedCardIds = Array.isArray(meleeUi.expandedCardIds)
    ? meleeUi.expandedCardIds
    : [];

  const alreadyExpanded = expandedCardIds.includes(cardId);

  meleeUi.expandedCardIds = alreadyExpanded
    ? expandedCardIds.filter((id) => id !== cardId)
    : [...expandedCardIds, cardId];
}

function handleInventoryToggleEquipped(draft, target) {
  const itemId = String(target.dataset.itemId ?? "");
  if (!itemId) {
    return;
  }

  const inventory = ensureInventoryState(draft);
  const item = inventory.items.find((entry) => entry.id === itemId);

  if (!item) {
    return;
  }

  const nextEquipped = !Boolean(item.equipped);

  if (item.type === "armor" && nextEquipped) {
    for (const entry of inventory.items) {
      if (entry.type === "armor") {
        entry.equipped = false;
      }
    }
  }

  item.equipped = nextEquipped;
}

function handleInventoryToggleExpand(draft, target) {
  const itemId = target.dataset.itemId;
  if (!itemId) {
    return;
  }

  const inventoryUi = ensureInventoryUiState(draft);
  const expandedItemIds = Array.isArray(inventoryUi.expandedItemIds)
    ? inventoryUi.expandedItemIds
    : [];

  const isExpanded = expandedItemIds.includes(itemId);

  inventoryUi.expandedItemIds = isExpanded
    ? expandedItemIds.filter((id) => id !== itemId)
    : [...expandedItemIds, itemId];
}

export function createActionHandlers({ resetState }) {
  return {
    "hp-change": handleHpChange,
    "hp-reset": handleHpReset,
    "toggle-abilities-edit": handleToggleAbilitiesEdit,
    "inventory-add-item": handleInventoryAddItem,
    "inventory-remove-item": handleInventoryRemoveItem,
    "long-rest": handleLongRest,
    "reset-runtime": () => handleResetRuntime(resetState),
    "short-rest": handleShortRest,
    "concentration-clear": handleConcentrationClear,
    "effect-add": handleEffectAdd,
    "effect-remove": handleEffectRemove,
    "print-sheet": handlePrintSheet,
    "ability-adjust": handleAbilityAdjust,
    "skill-toggle": handleSkillToggle,
    "saving-throw-toggle": handleSavingThrowToggle,
    "hp-apply-damage": handleHpApplyDamage,
    "hp-apply-heal": handleHpApplyHeal,
    "slot-set-used": handleSlotSetUsed,
    "bardic-set-current": handleBardicSetCurrent,
    "turn-toggle-action": handleTurnToggleAction,
    "turn-toggle-bonus-action": handleTurnToggleBonusAction,
    "turn-toggle-reaction": handleTurnToggleReaction,
    "turn-end": handleTurnEnd,
    "bardic-use": handleBardicUse,
    "weapon-attack": handleWeaponAttack,
    "spell-cast": handleSpellCast,
    "toggle-jack-of-all-trades": handleToggleJackOfAllTrades,
    "toggle-dueling-style": handleToggleDuelingStyle,
    "level-adjust": handleLevelAdjust,
    "spell-library-set-level": handleSpellLibrarySetLevel,
    "spell-library-set-selection-filter": handleSpellLibrarySetSelectionFilter,
    "spell-library-toggle-expand": handleSpellLibraryToggleExpand,
    "spell-library-toggle-select": handleSpellLibraryToggleSelect,
    "spells-toggle-expand": handleSpellsToggleExpand,
    "melee-toggle-expand": handleMeleeToggleExpand,
    "inventory-toggle-equipped": handleInventoryToggleEquipped,
    "inventory-toggle-expand": handleInventoryToggleExpand,
    "spell-library-search": handleSpellLibrarySearch,
    "spell-library-set-school": handleSpellLibrarySetSchool,
    "spell-library-toggle-flag": handleSpellLibraryToggleFlag,
  };
}

import { initTabs } from "./tabs.js";
import { getState, subscribe, setValue, updateState, resetState } from "./state.js";
import { getDerivedStats } from "./calculations.js";
import { renderPortraitMedia, initPortraitControls } from "./media.js";

import { renderHeader } from "./render/render-header.js";
import { renderQuickStats, renderSidebarSummary } from "./render/render-sidebar.js";
import { renderProfile } from "./render/render-profile.js";
import { renderMeleePanel } from "./render/render-melee.js";
import { renderSpells } from "./render/render-spells.js";
import { renderLorePanel } from "./render/render-lore.js";
import { renderInventoryPanel } from "./render/render-inventory.js";
import { renderSpellLibrary } from "./render/render-spell-library.js";

import { createActionHandlers, STATELESS_ACTIONS } from "./actions.js";
import {
  ensureEffectsState,
  ensureInventoryState,
} from "./state-helpers.js";

const actionHandlers = createActionHandlers({ resetState });

function parseInputValue(input) {
  if (input.type === "number") {
    if (input.value === "") {
      return 0;
    }

    return Number(input.value);
  }

  if (input.type === "checkbox") {
    return input.checked;
  }

  return input.value;
}

function setByPathOnObject(target, path, value) {
  const keys = String(path || "").split(".");
  const lastKey = keys.pop();

  if (!lastKey) {
    return;
  }

  let current = target;

  for (const key of keys) {
    if (current[key] == null || typeof current[key] !== "object") {
      current[key] = {};
    }

    current = current[key];
  }

  current[lastKey] = value;
}

function bindEditableFields(root = document) {
  root.querySelectorAll("[data-bind]").forEach((element) => {
    if (element.dataset.bound === "true") {
      return;
    }

    const isImmediate =
      element.type === "checkbox" ||
      element.dataset.bindImmediate === "true";

    const eventName = isImmediate ? "input" : "change";

    element.addEventListener(eventName, (event) => {
      const target = event.currentTarget;
      const path = target.dataset.bind;
      const value = parseInputValue(target);

      setValue(path, value);
    });

    element.dataset.bound = "true";
  });
}

function bindActionButtons(root = document) {
  root.querySelectorAll("[data-action]").forEach((element) => {
    if (element.dataset.bound === "true") {
      return;
    }

    const eventName = element.type === "checkbox" ? "change" : "click";

    element.addEventListener(eventName, (event) => {
      const target = event.currentTarget;
      const action = target.dataset.action;
      const handler = actionHandlers[action];

      if (!handler) {
        return;
      }

      if (STATELESS_ACTIONS.has(action)) {
        handler();
        return;
      }

      updateState((draft) => {
        handler(draft, target);
        return draft;
      });
    });

    element.dataset.bound = "true";
  });
}

function bindEffectFields(root = document) {
  root.querySelectorAll("[data-bind-effect-field]").forEach((element) => {
    if (element.dataset.bound === "true") {
      return;
    }

    const isImmediate =
      element.type === "checkbox" ||
      element.dataset.bindImmediate === "true";

    const eventName = isImmediate ? "input" : "change";

    element.addEventListener(eventName, (event) => {
      const target = event.currentTarget;
      const effectId = target.dataset.effectId;
      const field = target.dataset.bindEffectField;
      const value = target.type === "checkbox" ? target.checked : target.value;

      updateState((draft) => {
        const activeEffects = ensureEffectsState(draft);
        const effect = activeEffects.find((entry) => entry.id === effectId);

        if (!effect) {
          return draft;
        }

        effect[field] = value;
        return draft;
      });
    });

    element.dataset.bound = "true";
  });
}

function bindInventoryFields(root = document) {
  root.querySelectorAll("[data-bind-item-field]").forEach((element) => {
    if (element.dataset.bound === "true") {
      return;
    }

    const isImmediate =
      element.type === "checkbox" ||
      element.dataset.bindImmediate === "true";

    const eventName = isImmediate ? "input" : "change";

    element.addEventListener(eventName, (event) => {
      const target = event.currentTarget;
      const itemId = target.dataset.itemId;
      const field = target.dataset.bindItemField;

      let value;
      if (target.type === "checkbox") {
        value = target.checked;
      } else if (target.type === "number") {
        value = target.value === "" ? 0 : Number(target.value);
      } else {
        value = target.value;
      }

      updateState((draft) => {
        const inventory = ensureInventoryState(draft);
        const item = inventory.items.find((entry) => entry.id === itemId);

        if (!item) {
          return draft;
        }

        setByPathOnObject(item, field, value);
        return draft;
      });
    });

    element.dataset.bound = "true";
  });
}

function bindClickAction(root, selector, actionKey) {
  const handler = actionHandlers[actionKey];
  if (!handler) {
    return;
  }

  root.querySelectorAll(selector).forEach((element) => {
    if (element.dataset.bound === "true") {
      return;
    }

    element.addEventListener("click", (event) => {
      const target = event.currentTarget;

      updateState((draft) => {
        handler(draft, target);
        return draft;
      });
    });

    element.dataset.bound = "true";
  });
}

function bindSpellLibrarySearch(root = document) {
  root
    .querySelectorAll("[data-spell-library-search]")
    .forEach((element) => {
      if (element.dataset.bound === "true") {
        return;
      }

      element.addEventListener("input", (event) => {
        const target = event.currentTarget;
        const handler = actionHandlers["spell-library-search"];

        if (!handler) {
          return;
        }

        const selectionStart = target.selectionStart ?? target.value.length;
        const selectionEnd = target.selectionEnd ?? selectionStart;

        updateState((draft) => {
          handler(draft, target);
          return draft;
        });

        requestAnimationFrame(() => {
          const nextInput = document.querySelector(
            "[data-spell-library-search]",
          );

          if (!(nextInput instanceof HTMLInputElement)) {
            return;
          }

          nextInput.focus();

          const maxPosition = nextInput.value.length;

          nextInput.setSelectionRange(
            Math.min(selectionStart, maxPosition),
            Math.min(selectionEnd, maxPosition),
          );
        });
      });

      element.dataset.bound = "true";
    });
}

function bindSpellLibraryControls(root = document) {
  bindClickAction(root, "[data-spell-library-level]", "spell-library-set-level");
  bindClickAction(
    root,
    "[data-spell-library-selection]",
    "spell-library-set-selection-filter",
  );
  bindClickAction(root, "[data-spell-library-toggle]", "spell-library-toggle-expand");
  bindClickAction(root, "[data-spell-library-select]", "spell-library-toggle-select");
  bindSpellLibrarySearch(root);

  bindClickAction(
    root,
    "[data-spell-library-school]",
    "spell-library-set-school",
  );

  bindClickAction(
    root,
    "[data-spell-library-flag]",
    "spell-library-toggle-flag",
  );
}

function bindSpellsControls(root = document) {
  bindClickAction(root, "[data-spells-toggle]", "spells-toggle-expand");
}

function bindMeleeControls(root = document) {
  bindClickAction(root, "[data-melee-toggle]", "melee-toggle-expand");
}

function bindUi(root = document) {
  bindEditableFields(root);
  bindActionButtons(root);
  bindInventoryFields(root);
  bindEffectFields(root);
  bindSpellLibraryControls(root);
  bindSpellsControls(root);
  bindMeleeControls(root);
}

function renderApp() {
  const state = getState();
  const derived = getDerivedStats(state);

  const profilePanel = document.getElementById("profilePanel");
  const spellsPanel = document.getElementById("spellsPanel");
  const spellLibraryPanel = document.getElementById("spellLibraryPanel");

  renderHeader(state);
  renderPortraitMedia(state);
  renderQuickStats(state, derived);
  renderSidebarSummary(state);

  renderProfile(profilePanel, state, derived);
  renderMeleePanel(state, derived);
  renderSpells(spellsPanel, state, derived);
  renderSpellLibrary(spellLibraryPanel, state, derived);
  renderInventoryPanel(state);
  renderLorePanel(state);

  bindUi(document);
  initPortraitControls();
}

function getTelegramWebApp() {
  return window.Telegram?.WebApp ?? null;
}

function initTelegramWebApp() {
  const tg = getTelegramWebApp();

  if (!tg) {
    console.warn("Telegram WebApp SDK is unavailable");
    return null;
  }

  try {
    tg.ready();
    tg.expand();

    document.documentElement.style.setProperty(
      "--tg-bg-color",
      tg.themeParams?.bg_color || "",
    );
    document.documentElement.style.setProperty(
      "--tg-text-color",
      tg.themeParams?.text_color || "",
    );
  } catch (error) {
    console.error("Failed to initialize Telegram WebApp", error);
    return null;
  }

  return tg;
}

function initApp() {
  initTelegramWebApp();
  initTabs();
  renderApp();
}

function debugDerived(character) {
  const derived = getDerivedStats(character);

  console.group("Derived debug");
  console.log("hasJackOfAllTrades", derived.hasJackOfAllTrades);
  console.log("abilityModifiers", derived.abilityModifiers);
  console.log("abilityChecks", derived.abilityChecks);
  console.log("savingThrows", derived.savingThrows);
  console.log("skills", derived.skills);
  console.log("spellSaveDc", derived.spellStats?.spellSaveDc);
  console.log("spellAttackBonus", derived.spellStats?.spellAttackBonus);
  console.log("initiative", derived.initiative);
  console.log("passivePerception", derived.passivePerception);
  console.groupEnd();
}

window.debug = {
  getState: () => getState(),
  getDerivedStats: (state) => getDerivedStats(state),
  debugDerived: (state) => debugDerived(state),
  subscribe: (listener) => subscribe(listener),
};

subscribe(() => {
  renderApp();
});

initApp();

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any


PROJECT_ROOT = Path(__file__).resolve().parent.parent

INPUT_FILE = PROJECT_ROOT / "data" / "bard_spells_parsed.json"
OUTPUT_FILE = PROJECT_ROOT / "data" / "bard-spells.generated.js"

WHITESPACE_RE = re.compile(r"\s+")
SENTENCE_END_RE = re.compile(r"(?<=[.!?])\s+")
LEGACY_ID_BY_SLUG = {
    "tasha-s-hideous-laughter": "tashas-hideous-laughter-2014",
    "raulothim-s-psychic-lance": "raulothims-psychic-lance-2014",
}


def normalize_inline(value: str) -> str:
    return WHITESPACE_RE.sub(" ", value).strip()


def truncate_sentence_safe(value: str, max_chars: int) -> str:
    text = normalize_inline(value)

    if len(text) <= max_chars:
        return text

    sentences = SENTENCE_END_RE.split(text)
    result: list[str] = []
    current_length = 0

    for sentence in sentences:
        next_length = current_length + len(sentence) + (1 if result else 0)

        if result and next_length > max_chars:
            break

        if not result and len(sentence) > max_chars:
            return sentence[: max_chars - 1].rstrip() + "…"

        result.append(sentence)
        current_length = next_length

    if not result:
        return text[: max_chars - 1].rstrip() + "…"

    summary = " ".join(result)

    if len(summary) < len(text):
        return summary.rstrip(".") + "…"

    return summary


def build_summary(spell: dict[str, Any]) -> str:
    paragraphs = [
        normalize_inline(part)
        for part in spell["full_description"].split("\n\n")
        if normalize_inline(part)
    ]

    if not paragraphs:
        return "Описание отсутствует."

    summary = truncate_sentence_safe(paragraphs[0], max_chars=340)

    if len(summary) < 140 and len(paragraphs) > 1:
        summary = truncate_sentence_safe(
            f"{summary} {paragraphs[1]}",
            max_chars=370,
        )

    return summary


def normalize_available_from_level(level: int) -> int:
    """Bard spell availability starts at character level 1 for cantrips."""

    if level == 0:
        return 1

    return max(1, 2 * level - 1)


def to_frontend_spell(source: dict[str, Any]) -> dict[str, Any]:
    level = int(source["level"])
    slug = source["slug"]

    spell_id = LEGACY_ID_BY_SLUG.get(
        slug,
        f"{slug}-2014",
    )

    return {
        "id": spell_id,
        "name": source["name_ru"],
        "originalName": source.get("name_en"),
        "source": "class",
        "sourceLabel": "Бард",
        "sourceBook": source.get("source"),
        "level": level,
        "school": source["school"],
        "ritual": bool(source["ritual"]),
        "concentration": bool(source["concentration"]),
        "castTime": source["casting_time"],
        "range": source["range_value"],
        "components": source["components"],
        "duration": source["duration"],
        "summary": build_summary(source),
        "description": source["full_description"],
        "upcast": source.get("upcast_text"),
        "classes": source.get("classes", []),
        "subclasses": source.get("subclasses", []),
        "availableFromLevel": normalize_available_from_level(level),
    }


def validate_spells(spells: list[dict[str, Any]]) -> None:
    spell_ids = [spell["id"] for spell in spells]

    duplicate_ids = sorted(
        {
            spell_id
            for spell_id in spell_ids
            if spell_ids.count(spell_id) > 1
        }
    )

    if duplicate_ids:
        raise ValueError(
            "Найдены дублирующиеся spell ID: "
            + ", ".join(duplicate_ids)
        )

    required_fields = {
        "id",
        "name",
        "level",
        "school",
        "castTime",
        "range",
        "components",
        "duration",
        "summary",
        "description",
        "availableFromLevel",
    }

    for spell in spells:
        missing = required_fields - spell.keys()

        if missing:
            raise ValueError(
                f"У {spell.get('id')!r} не хватает полей: "
                + ", ".join(sorted(missing))
            )

        if not spell["name"].strip():
            raise ValueError(
                f"У {spell['id']!r} пустое имя."
            )


def render_module(spells: list[dict[str, Any]]) -> str:
    payload = json.dumps(
        spells,
        ensure_ascii=False,
        indent=2,
    )

    return f"""// AUTO-GENERATED FILE.
// Source: data/bard_spells_parsed.json
// Builder: scripts/build_frontend_spell_library.py
// Do not edit manually.

export const BARD_SPELL_LIBRARY = {payload};

export const BARD_SPELL_LIBRARY_BY_ID = Object.fromEntries(
  BARD_SPELL_LIBRARY.map((spell) => [spell.id, spell]),
);
"""


def main() -> None:
    if not INPUT_FILE.exists():
        raise FileNotFoundError(
            f"Не найден источник: {INPUT_FILE}"
        )

    payload = json.loads(INPUT_FILE.read_text(encoding="utf-8"))

    if payload.get("schema_version") != 1:
        raise ValueError(
            "Неподдерживаемая схема JSON: "
            f"{payload.get('schema_version')!r}"
        )

    spells = [
        to_frontend_spell(spell)
        for spell in payload.get("spells", [])
    ]

    if not spells:
        raise ValueError("В JSON нет заклинаний.")

    validate_spells(spells)

    OUTPUT_FILE.write_text(
        render_module(spells),
        encoding="utf-8",
    )

    by_level = {
        level: sum(spell["level"] == level for spell in spells)
        for level in range(10)
    }

    print(f"Сгенерировано заклинаний: {len(spells)}")

    for level, count in by_level.items():
        label = "Заговоры" if level == 0 else f"{level} уровень"
        print(f"  - {label}: {count}")

    print(f"Файл: {OUTPUT_FILE}")


if __name__ == "__main__":
    main()

import {
  ABILITY_KEYS,
  SKILL_ID_META,
  PROFICIENCY_BY_LEVEL,
  BARD_PROGRESSION,
  TURN_TRACKER_META,
} from "./rules.js";
import { buildCharacterSpellCollections } from "./selectors/spellcasting.js";

function getAbilityModifier(score = 10) {
  return Math.floor((Number(score) - 10) / 2);
}

function formatSigned(value) {
  const number = Number(value) || 0;
  return number >= 0 ? `+${number}` : `${number}`;
}

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function getLevel(character) {
  return Math.max(1, Number(character.profile?.level ?? 1));
}

function getProficiencyBonus(level, override = null) {
  if (override != null && override !== "") {
    return Number(override);
  }

  return (
    PROFICIENCY_BY_LEVEL.find((row) => level >= row.min && level <= row.max)?.value ?? 2
  );
}

function hasFeature(character, featureName) {
  const level = getLevel(character);
  const features = Array.isArray(character.classFeatures) ? character.classFeatures : [];

  return features.some(
    (feature) =>
      feature?.name === featureName &&
      Number(feature?.level ?? 0) <= level,
  );
}

function hasJackOfAllTrades(character) {
  const disabledByUi = Boolean(character.ui?.rulesOverrides?.disableJackOfAllTrades);
  return hasFeature(character, "Мастер на все руки") && !disabledByUi;
}

function hasDuelingStyle(character) {
  const disabledByUi = Boolean(character.ui?.rulesOverrides?.disableDuelingStyle);
  const fightingStyleName = String(character.combat?.fightingStyle?.name ?? "").trim();

  return fightingStyleName === "Дуэлянт" && !disabledByUi;
}

function getAbilityModifiers(character) {
  const abilities = character.abilities ?? {};

  return ABILITY_KEYS.reduce((acc, key) => {
    acc[key] = getAbilityModifier(abilities[key]);
    return acc;
  }, {});
}

function getAbilityChecks(abilityModifiers, proficiencyBonus, hasJoat) {
  const halfProf = hasJoat ? Math.floor(proficiencyBonus / 2) : 0;

  return ABILITY_KEYS.reduce((acc, key) => {
    acc[key] = (abilityModifiers[key] ?? 0) + halfProf;
    return acc;
  }, {});
}

function getSavingThrows(character, abilityModifiers, proficiencyBonus) {
  const savingThrows = character.savingThrows ?? {};

  return ABILITY_KEYS.reduce((acc, key) => {
    const proficient = Boolean(savingThrows[key]?.proficient);
    acc[key] = (abilityModifiers[key] ?? 0) + (proficient ? proficiencyBonus : 0);
    return acc;
  }, {});
}

function getSkillValue(skill, abilityModifiers, proficiencyBonus, hasJoat) {
  const abilityKey = skill?.ability ?? null;
  const abilityMod = abilityKey ? abilityModifiers[abilityKey] ?? 0 : 0;

  if (skill?.expertise) {
    return abilityMod + proficiencyBonus * 2;
  }

  if (skill?.proficient) {
    return abilityMod + proficiencyBonus;
  }

  return abilityMod + (hasJoat ? Math.floor(proficiencyBonus / 2) : 0);
}

function getSkills(character, abilityModifiers, proficiencyBonus, hasJoat) {
  const skills = Array.isArray(character.skills) ? character.skills : [];
  const byId = new Map(skills.filter((skill) => skill?.id).map((skill) => [skill.id, skill]));

  return Object.entries(SKILL_ID_META).reduce((acc, [skillId, meta]) => {
    const sourceSkill = byId.get(skillId) ?? {
      id: skillId,
      name: meta.label,
      ability: meta.ability,
      proficient: false,
      expertise: false,
      source: null,
    };

    const value = getSkillValue(sourceSkill, abilityModifiers, proficiencyBonus, hasJoat);

    acc[skillId] = value;
    acc[meta.label] = value;
    return acc;
  }, {});
}

function getInventoryItems(character) {
  return Array.isArray(character.inventory?.items) ? character.inventory.items : [];
}

function getEquippedItems(character) {
  return getInventoryItems(character).filter((item) => item?.equipped);
}

function getEquippedItemsByType(character, type) {
  return getEquippedItems(character).filter((item) => item?.type === type);
}

function getEquippedArmor(character) {
  return getEquippedItemsByType(character, "armor")[0] ?? null;
}

function getEquippedWeapons(character) {
  return getEquippedItemsByType(character, "weapon").filter((item) => item?.weapon);
}

function getArmorClass(character, abilityModifiers) {
  const dexMod = abilityModifiers.dexterity ?? 0;
  const miscBonus = Number(character.combat?.armorBonusExtra ?? 0);
  const shieldBonus = Number(character.combat?.shieldBonus ?? 0);

  const equippedArmor = getEquippedArmor(character);

  if (!equippedArmor?.armor) {
    return 10 + dexMod + shieldBonus + miscBonus;
  }

  const armor = equippedArmor.armor;
  const baseAc = Number(armor.baseAc ?? 10);
  const dexCap = armor.dexCap;
  const magicalBonusAc = Number(armor.magicalBonusAc ?? 0);
  const appliedDex = dexCap == null ? dexMod : Math.min(dexMod, Number(dexCap));

  return baseAc + appliedDex + magicalBonusAc + shieldBonus + miscBonus;
}

function getMaxHitPoints(character, abilityModifiers) {
  const override = character.combat?.hp?.maxOverride;
  if (override != null && override !== "") {
    return Number(override);
  }

  const explicitMax = character.combat?.hp?.max;
  if (explicitMax != null && explicitMax !== "") {
    return Number(explicitMax);
  }

  const level = getLevel(character);
  const hitDie = Number(character.combat?.hitDie ?? 8);
  const conMod = abilityModifiers.constitution ?? 0;
  const averagePerLevelAfterFirst = Math.floor(hitDie / 2) + 1;

  return hitDie + conMod + (level - 1) * (averagePerLevelAfterFirst + conMod);
}

function getCurrentHitPoints(character, maxHitPoints) {
  const current = Number(character.combat?.hp?.current ?? maxHitPoints);
  return clamp(current, 0, maxHitPoints);
}

function getInitiative(character, abilityModifiers, proficiencyBonus, hasJoat) {
  const dexMod = abilityModifiers.dexterity ?? 0;
  const extra = Number(character.combat?.initiativeBonusExtra ?? 0);
  const halfProf = hasJoat ? Math.floor(proficiencyBonus / 2) : 0;

  return dexMod + extra + halfProf;
}

function getBardProgression(character) {
  const level = getLevel(character);
  const fallback = {
    cantripsKnown: 0,
    spellsKnown: 0,
    bardicDie: null,
    bardicUses: 0,
    slots: {},
  };

  if (character.profile?.className !== "Бард") {
    return fallback;
  }

  return BARD_PROGRESSION[level] ?? fallback;
}

function getWeaponDerivedList(character, abilityModifiers, proficiencyBonus) {
  const weapons = getEquippedWeapons(character);

  return weapons.map((item) => {
    const weapon = item.weapon ?? {};
    const attackStat = weapon.attackStat ?? "strength";
    const abilityMod = abilityModifiers[attackStat] ?? 0;

    const isMeleeWeapon = weapon.category !== "ranged";
    const isOneHanded = !Boolean(weapon.twoHanded);

    const duelingApplies =
      hasDuelingStyle(character) &&
      isMeleeWeapon &&
      isOneHanded;

    const styleDamageBonus = duelingApplies
      ? Number(character.combat?.fightingStyle?.damageBonus ?? 0)
      : 0;

    const magicalBonusAttack = Number(weapon.magicalBonusAttack ?? 0);
    const magicalBonusDamage = Number(weapon.magicalBonusDamage ?? 0);

    const attackBonus = abilityMod + proficiencyBonus + magicalBonusAttack;
    const damageBonus = abilityMod + styleDamageBonus + magicalBonusDamage;

    return {
      id: item.id,
      name: item.name,
      attackStat,
      attackBonus,
      formattedAttackBonus: formatSigned(attackBonus),
      damageDice: weapon.damageDice ?? "—",
      damageBonus,
      formattedDamageBonus: formatSigned(damageBonus),
      damageType: weapon.damageType ?? "—",
      properties: Array.isArray(weapon.properties) ? weapon.properties : [],
      notes: item.notes ?? "",
      duelingApplies,
    };
  });
}

function getSpellStats(character, abilityModifiers, proficiencyBonus) {
  const spellcasting = character.spellcasting ?? {};
  const spellAbility = spellcasting.ability ?? "charisma";
  const spellMod = abilityModifiers[spellAbility] ?? 0;

  const spellSaveDc =
    spellcasting.spellSaveDcOverride != null
      ? Number(spellcasting.spellSaveDcOverride)
      : 8 + proficiencyBonus + spellMod;

  const spellAttackBonus =
    spellcasting.spellAttackBonusOverride != null
      ? Number(spellcasting.spellAttackBonusOverride)
      : proficiencyBonus + spellMod;

  return {
    spellcastingAbility: spellAbility,
    spellcastingModifier: spellMod,
    spellSaveDc,
    spellAttackBonus,
    formattedSpellAttackBonus: formatSigned(spellAttackBonus),
  };
}

export function formatSpellSave(spell, spellSaveDc) {
  if (spell?.save) {
    return spell.save;
  }

  if (!spell?.saveAbility) {
    return null;
  }

  const map = {
    strength: "Сила",
    dexterity: "Ловкость",
    constitution: "Телосложение",
    intelligence: "Интеллект",
    wisdom: "Мудрость",
    charisma: "Харизма",
  };

  if (spellSaveDc == null) {
    return map[spell.saveAbility] ?? spell.saveAbility;
  }

  return `${map[spell.saveAbility] ?? spell.saveAbility} ${spellSaveDc}`;
}

export function formatSpellDamage(spell, spellcastingModifier) {
  if (!spell?.damage) {
    return null;
  }

  if (typeof spell.damage === "string") {
    return spell.damage;
  }

  const modifier =
    spell.damage.modifier === "spellcasting"
      ? spellcastingModifier
      : Number(spell.damage.modifier ?? 0);

  const modifierPart = modifier === 0 ? "" : ` ${formatSigned(modifier)}`;

  return `${spell.damage.dice}${modifierPart} ${spell.damage.type}`.trim();
}

export function formatHealing(spell, spellcastingModifier) {
  if (!spell?.healing) {
    return null;
  }

  const modifier =
    spell.healing.modifier === "spellcasting"
      ? spellcastingModifier
      : Number(spell.healing.modifier ?? 0);

  const modifierPart = modifier === 0 ? "" : ` ${formatSigned(modifier)}`;

  return `${spell.healing.dice}${modifierPart} лечение`.trim();
}

function formatDiceWithModifier(dice, modifier) {
  const numericModifier = Number(modifier ?? 0);

  if (!numericModifier) {
    return dice;
  }

  return `${dice} ${formatSigned(numericModifier)}`;
}

function isSpellAvailable(character, spell) {
  const level = getLevel(character);

  if (spell?.availableFromLevel && level < Number(spell.availableFromLevel)) {
    return false;
  }

  if (spell?.locked) {
    return false;
  }

  return true;
}

function inferCombatRole(spell) {
  if (spell?.combatRole) {
    return spell.combatRole;
  }

  if (spell?.damage || spell?.healing) {
    return "combat";
  }

  if (spell?.concentration) {
    return "combat";
  }

  const originalName = String(spell?.originalName || "").toLowerCase();
  const name = String(spell?.name || "").toLowerCase();

  const knownCombatSpells = [
    "vicious mockery",
    "tasha’s hideous laughter",
    "tasha's hideous laughter",
    "dissonant whispers",
    "cure wounds",
    "healing word",
    "mirror image",
    "язвительная насмешка",
    "безудержный смех",
    "диссонирующий шёпот",
    "исцеление ран",
    "исцеляющее слово",
    "зеркальное отражение",
  ];

  if (knownCombatSpells.includes(originalName) || knownCombatSpells.includes(name)) {
    return "combat";
  }

  return "utility";
}

function getCombatSpells(character, spellStats) {
  const collections = buildCharacterSpellCollections(character);
  const spells = [
    ...(collections.cantrips || []),
    ...(collections.preparedSpells || []),
    ...(collections.grantedSpells || []),
  ];

  return spells
    .filter((spell) => isSpellAvailable(character, spell))
    .filter((spell) => inferCombatRole(spell) !== "utility")
    .map((spell) => ({
      id: `spell-${String(spell.originalName ?? spell.name ?? "")
        .toLowerCase()
        .replaceAll(" ", "-")}`,
      spellId: spell.id ?? null,
      kind: "spell",
      title: spell.name ?? "",
      originalName: spell.originalName ?? null,
      level: Number(spell.level ?? 0),
      school: spell.school ?? null,
      attack: spell.attackBonus ?? (spell.attackType ? spellStats.formattedSpellAttackBonus : null),
      save: formatSpellSave(spell, spellStats.spellSaveDc),
      damage:
        formatSpellDamage(spell, spellStats.spellcastingModifier) ??
        formatHealing(spell, spellStats.spellcastingModifier),
      concentration: Boolean(spell.concentration),
      castTime: spell.castTime ?? spell.castingTime ?? "",
      range: spell.range ?? "",
      rangeFeet:
        spell.rangeFeet !== null && spell.rangeFeet !== undefined
          ? Number(spell.rangeFeet)
          : null,
      areaShape: spell.areaShape ?? null,
      areaSizeFeet:
        spell.areaSizeFeet !== null && spell.areaSizeFeet !== undefined
          ? Number(spell.areaSizeFeet)
          : null,
      areaType: spell.areaType ?? null,
      duration: spell.duration ?? "",
      tags: [spell.sourceLabel, spell.school, spell.combatRole ?? inferCombatRole(spell)].filter(Boolean),
      notes: spell.vibe ?? spell.description ?? spell.notes ?? "",
    }));
}

function getCombatFeatures(character) {
  const flourishes = Array.isArray(character.combat?.flourishes) ? character.combat.flourishes : [];

  return flourishes.map((flourish) => ({
    id: `flourish-${String(flourish.name || "").toLowerCase().replaceAll(" ", "-")}`,
    kind: "feature",
    title: flourish.name || "Росчерк",
    cost: flourish.cost || "",
    notes: flourish.text || "",
    tags: ["Росчерк клинка"],
  }));
}

function getCombatCards(character, derivedBase) {
  const weapons = derivedBase.weapons.map((weapon) => ({
    id: weapon.id,
    kind: "weapon",
    title: weapon.name,
    attack: weapon.formattedAttackBonus,
    damage: formatDiceWithModifier(weapon.damageDice, weapon.damageBonus),
    damageType: weapon.damageType,
    tags: weapon.properties,
    notes: weapon.notes,
  }));

  return {
    weapons,
    features: getCombatFeatures(character),
    spells: getCombatSpells(character, derivedBase.spellStats),
  };
}

function getSpellSlotsState(character, bardProgression) {
  const usedMap = character.spellcasting?.slotsUsed ?? character.spellcasting?.slots ?? {};
  const levels = Object.keys(bardProgression.slots ?? {}).map(Number).sort((a, b) => a - b);

  return levels.map((level) => {
    const max = Number(bardProgression.slots[level] ?? 0);
    const rawUsed = Number(usedMap[level]?.used ?? usedMap[level] ?? 0);
    const used = clamp(rawUsed, 0, max);

    return {
      level,
      max,
      used,
      available: Math.max(0, max - used),
    };
  });
}

function getPassivePerception(skills, abilityChecks) {
  if (typeof skills.perception === "number") {
    return 10 + skills.perception;
  }

  if (typeof skills["Восприятие"] === "number") {
    return 10 + skills["Восприятие"];
  }

  return 10 + (abilityChecks.wisdom ?? 0);
}

function getTurnTracker(character) {
  const turn = character.ui?.turn ?? {};

  return {
    turnNumber: Math.max(1, Number(turn.turnNumber ?? 1)),
    items: TURN_TRACKER_META.map((item) => {
      const used = Boolean(turn[item.key]);

      return {
        key: item.key,
        label: item.label,
        used,
        ready: !used,
        stateLabel: used ? item.usedLabel : item.readyLabel,
      };
    }),
  };
}

function getBardicInspirationState(character, bardProgression, abilityModifiers) {
  const max = Math.max(1, Number(abilityModifiers.charisma ?? 0));
  const current = clamp(Number(character.combat?.bardicInspiration?.current ?? max), 0, max);

  return {
    dice: bardProgression.bardicDie,
    max,
    current,
    refresh: character.combat?.bardicInspiration?.refresh ?? "Долгий отдых",
    rangeFeet: Number(character.combat?.bardicInspiration?.rangeFeet ?? 60),
    rangeMeters: Number(character.combat?.bardicInspiration?.rangeMeters ?? 18),
    duration: character.combat?.bardicInspiration?.duration ?? "10 минут",
    notes: character.combat?.bardicInspiration?.notes ?? "",
  };
}

export function getDerivedStats(character) {
  const level = getLevel(character);
  const proficiencyBonus = getProficiencyBonus(
    level,
    character.profile?.proficiencyBonusOverride ?? null,
  );
  const joat = hasJackOfAllTrades(character);
  const abilityModifiers = getAbilityModifiers(character);
  const abilityChecks = getAbilityChecks(abilityModifiers, proficiencyBonus, joat);
  const savingThrows = getSavingThrows(character, abilityModifiers, proficiencyBonus);
  const skills = getSkills(character, abilityModifiers, proficiencyBonus, joat);
  const armorClass = getArmorClass(character, abilityModifiers);
  const maxHitPoints = getMaxHitPoints(character, abilityModifiers);
  const currentHitPoints = getCurrentHitPoints(character, maxHitPoints);
  const initiative = getInitiative(character, abilityModifiers, proficiencyBonus, joat);
  const bardProgression = getBardProgression(character);
  const weapons = getWeaponDerivedList(character, abilityModifiers, proficiencyBonus);
  const spellStats = getSpellStats(character, abilityModifiers, proficiencyBonus);
  const spellSlots = getSpellSlotsState(character, bardProgression);
  const bardicInspiration = getBardicInspirationState(
    character,
    bardProgression,
    abilityModifiers,
  );

  const derivedBase = {
    level,
    proficiencyBonus,
    hasJackOfAllTrades: joat,
    abilityModifiers,
    abilityChecks,
    savingThrows,
    skills,
    armorClass,
    maxHitPoints,
    currentHitPoints,
    tempHitPoints: Number(character.combat?.hp?.temp ?? 0),
    initiative,
    formattedInitiative: formatSigned(initiative),
    passivePerception: getPassivePerception(skills, abilityChecks),
    spellStats,
    spellSaveDc: spellStats.spellSaveDc,
    spellAttackBonus: spellStats.spellAttackBonus,
    formattedSpellAttackBonus: spellStats.formattedSpellAttackBonus,
    weapons,
    spellSlots,
    bardicInspiration,
    bardProgression,
    cantripsKnown: bardProgression.cantripsKnown,
    spellsKnown: bardProgression.spellsKnown,
  };

  return {
    ...derivedBase,
    combatCards: getCombatCards(character, derivedBase),
    turnTracker: getTurnTracker(character),
    maxHp: maxHitPoints,
    maxHpLegacy: maxHitPoints,
    currentHp: currentHitPoints,
  };
}

let currentObjectUrl = null;
let defaultMediaConfig = null;
let lastRenderedMediaKey = null;

function getMediaKind(media) {
  if (!media || !media.src) return "image";

  if (media.type) return media.type;

  const src = media.src.toLowerCase();

  if (src.endsWith(".mp4") || src.endsWith(".webm")) return "video";
  if (src.endsWith(".gif")) return "gif";

  return "image";
}

function getMediaRenderKey(media) {
  if (!media) {
    return "null";
  }

  return JSON.stringify({
    type: media.type || "",
    src: media.src || "",
    poster: media.poster || "",
    alt: media.alt || ""
  });
}

function getMediaKindFromFile(file) {
  const type = file.type.toLowerCase();
  const name = file.name.toLowerCase();

  if (type.startsWith("video/") || name.endsWith(".mp4") || name.endsWith(".webm")) {
    return "video";
  }

  if (type === "image/gif" || name.endsWith(".gif")) {
    return "gif";
  }

  return "image";
}

function cleanupObjectUrl() {
  if (currentObjectUrl) {
    URL.revokeObjectURL(currentObjectUrl);
    currentObjectUrl = null;
  }
}

function setToggleButtonState(hasVideo, paused = false) {
  const toggleBtn = document.getElementById("togglePortraitMotionBtn");
  if (!toggleBtn) return;

  let icon = toggleBtn.querySelector(".portrait-toggle-btn__icon");
  if (!icon) {
    icon = document.createElement("span");
    icon.className = "portrait-toggle-btn__icon";
    toggleBtn.innerHTML = "";
    toggleBtn.appendChild(icon);
  }

  toggleBtn.disabled = !hasVideo;
  toggleBtn.classList.toggle("is-paused", hasVideo && paused);
  toggleBtn.classList.toggle("is-disabled", !hasVideo);
  toggleBtn.setAttribute("aria-pressed", hasVideo ? String(paused) : "false");

  if (!hasVideo) {
    icon.textContent = "▶";
    toggleBtn.setAttribute("aria-label", "Анимация недоступна");
    toggleBtn.setAttribute("title", "Анимация недоступна");
    return;
  }

  icon.textContent = paused ? "▶" : "❚❚";
  toggleBtn.setAttribute(
    "aria-label",
    paused ? "Запустить анимацию" : "Пауза анимации"
  );
  toggleBtn.setAttribute(
    "title",
    paused ? "Воспроизвести" : "Пауза"
  );
}

function bindPortraitVideoState(video) {
  if (!video || video.dataset.stateBound === "true") {
    return;
  }

  const sync = () => {
    setToggleButtonState(true, video.paused);
  };

  video.addEventListener("play", sync);
  video.addEventListener("pause", sync);
  video.addEventListener("ended", sync);

  video.dataset.stateBound = "true";
  sync();
}

function renderPortraitMarkup(media) {
  const portraitStage = document.getElementById("portraitStage");
  if (!portraitStage) return;

  const nextMediaKey = getMediaRenderKey(media);
  if (nextMediaKey === lastRenderedMediaKey) {
    return;
  }

  lastRenderedMediaKey = nextMediaKey;

  const toggleBtn = document.getElementById("togglePortraitMotionBtn");
  const mediaKind = getMediaKind(media);

  let mediaMarkup = "";
  let hasVideo = false;

  if (!media || !media.src) {
    mediaMarkup = `
      <img
        class="portrait-poster"
        src="./assets/portrait.png"
        alt="Портрет персонажа"
      />
    `;
  } else if (mediaKind === "video") {
    const mimeType =
      media.src.toLowerCase().endsWith(".webm") ? "video/webm" : "video/mp4";

    mediaMarkup = `
      <video
        class="portrait-media portrait-media--video"
        id="portraitVideo"
        autoplay
        muted
        loop
        playsinline
        preload="metadata"
        poster="${media.poster || ""}"
        aria-label="${media.alt || "Анимированный портрет персонажа"}"
      >
        <source src="${media.src}" type="${mimeType}" />
      </video>
    `;
    hasVideo = true;
  } else {
    mediaMarkup = `
      <img
        class="portrait-media"
        src="${media.src}"
        alt="${media.alt || "Портрет персонажа"}"
      />
    `;
  }

  portraitStage.innerHTML = mediaMarkup;

  if (toggleBtn) {
    portraitStage.appendChild(toggleBtn);
  }

  if (hasVideo) {
    const video = document.getElementById("portraitVideo");
    if (video) {
      video.muted = true;
      bindPortraitVideoState(video);

      const playPromise = video.play();
      if (playPromise && typeof playPromise.catch === "function") {
        playPromise.catch(() => {
          console.warn("Автовоспроизведение портрета было заблокировано браузером");
          setToggleButtonState(true, true);
        });
      }
    } else {
      setToggleButtonState(true, true);
    }
  } else {
    setToggleButtonState(false, true);
  }
}

export function renderPortraitMedia(state) {
  defaultMediaConfig = structuredClone(state.profile.media || null);
  renderPortraitMarkup(defaultMediaConfig);
}

export function initPortraitControls() {
  const toggleBtn = document.getElementById("togglePortraitMotionBtn");
  const fileInput = document.getElementById("portraitFileInput");
  const resetBtn = document.getElementById("resetPortraitBtn");

  if (toggleBtn && !toggleBtn.dataset.bound) {
    toggleBtn.addEventListener("click", () => {
      const video = document.getElementById("portraitVideo");
      if (!video) return;

      if (video.paused) {
        const playPromise = video.play();
        if (playPromise && typeof playPromise.catch === "function") {
          playPromise.catch(() => {
            setToggleButtonState(true, true);
          });
        }
      } else {
        video.pause();
      }
    });

    toggleBtn.dataset.bound = "true";
  }

  if (fileInput && !fileInput.dataset.bound) {
    fileInput.addEventListener("change", (event) => {
      const file = event.target.files?.[0];
      if (!file) return;

      cleanupObjectUrl();
      currentObjectUrl = URL.createObjectURL(file);

      const mediaKind = getMediaKindFromFile(file);

      const localMedia = {
        type: mediaKind,
        src: currentObjectUrl,
        poster:
          mediaKind === "video"
            ? (defaultMediaConfig?.poster || "./assets/portrait.png")
            : "",
        alt: `Локальный файл: ${file.name}`
      };

      lastRenderedMediaKey = null;
      renderPortraitMarkup(localMedia);
    });

    fileInput.dataset.bound = "true";
  }

  if (resetBtn && !resetBtn.dataset.bound) {
    resetBtn.addEventListener("click", () => {
      cleanupObjectUrl();
      lastRenderedMediaKey = null;

      if (fileInput) {
        fileInput.value = "";
      }

      renderPortraitMarkup(defaultMediaConfig);
    });

    resetBtn.dataset.bound = "true";
  }
}

