import { character } from "../data/character.js";
import {
  buildInitialState,
  savePersistedState,
  clearPersistedState
} from "./storage.js";

let state = buildInitialState(character);
const listeners = new Set();

function notify() {
  listeners.forEach((listener) => listener(state));
}

function cloneState(value) {
  return structuredClone(value);
}

function getByPath(obj, path) {
  return path.split(".").reduce((acc, key) => acc?.[key], obj);
}

function setByPath(obj, path, value) {
  const keys = path.split(".");
  const lastKey = keys.pop();

  let current = obj;
  for (const key of keys) {
    if (current[key] == null || typeof current[key] !== "object") {
      current[key] = {};
    }
    current = current[key];
  }

  current[lastKey] = value;
}

function commit(nextState) {
  state = nextState;
  savePersistedState(state);
  notify();
}

export function getState() {
  return state;
}

export function subscribe(listener) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

export function setValue(path, value) {
  const draft = cloneState(state);
  setByPath(draft, path, value);
  commit(draft);
}

export function updateState(updater) {
  const draft = cloneState(state);
  const nextDraft = updater(draft) ?? draft;
  commit(nextDraft);
}

export function resetState() {
  state = structuredClone(character);
  clearPersistedState();
  notify();
}

export function getValue(path) {
  return getByPath(state, path);
}

const STORAGE_KEY = "aurelia-character-sheet:v2";

const SKILL_LABELS = {
  athletics: "Атлетика",
  acrobatics: "Акробатика",
  sleightOfHand: "Ловкость рук",
  stealth: "Скрытность",
  arcana: "Магия",
  history: "История",
  investigation: "Расследование",
  nature: "Природа",
  religion: "Религия",
  animalHandling: "Уход за животными",
  insight: "Проницательность",
  medicine: "Медицина",
  perception: "Восприятие",
  survival: "Выживание",
  deception: "Обман",
  intimidation: "Запугивание",
  performance: "Выступление",
  persuasion: "Убеждение"
};

const SKILL_TO_ABILITY = {
  athletics: "strength",
  acrobatics: "dexterity",
  sleightOfHand: "dexterity",
  stealth: "dexterity",
  arcana: "intelligence",
  history: "intelligence",
  investigation: "intelligence",
  nature: "intelligence",
  religion: "intelligence",
  animalHandling: "wisdom",
  insight: "wisdom",
  medicine: "wisdom",
  perception: "wisdom",
  survival: "wisdom",
  deception: "charisma",
  intimidation: "charisma",
  performance: "charisma",
  persuasion: "charisma"
};

function normalizeSkills(skills) {
  if (!Array.isArray(skills)) {
    return [];
  }

  const byId = new Map();

  for (const raw of skills) {
    if (!raw || typeof raw !== "object") {
      continue;
    }

    let canonicalId = raw.id ?? null;

    if (!canonicalId && raw.name) {
      canonicalId =
        Object.entries(SKILL_LABELS).find(([, label]) => label === raw.name)?.[0] ??
        null;
    }

    if (!canonicalId || !SKILL_LABELS[canonicalId]) {
      continue;
    }

    const proficient = Boolean(raw.proficient);
    const expertise = Boolean(raw.expertise);

    const normalized = {
      id: canonicalId,
      name: SKILL_LABELS[canonicalId],
      ability: SKILL_TO_ABILITY[canonicalId],
      proficient: proficient || expertise,
      expertise,
      source: raw.source ?? null,
    };

    const existing = byId.get(canonicalId);
    if (!existing) {
      byId.set(canonicalId, normalized);
      continue;
    }

    byId.set(canonicalId, {
      ...existing,
      ...normalized,
      proficient: Boolean(existing.proficient || normalized.proficient),
      expertise: Boolean(existing.expertise || normalized.expertise),
      source: existing.source ?? normalized.source ?? null,
    });
  }

  return Array.from(byId.values());
}

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function deepMerge(base, override) {
  if (Array.isArray(base) || Array.isArray(override)) {
    return override ?? base;
  }

  if (!isPlainObject(base) || !isPlainObject(override)) {
    return override ?? base;
  }

  const result = { ...base };

  for (const [key, overrideValue] of Object.entries(override)) {
    const baseValue = base[key];

    if (Array.isArray(overrideValue)) {
      result[key] = overrideValue;
      continue;
    }

    if (isPlainObject(overrideValue) && isPlainObject(baseValue)) {
      result[key] = deepMerge(baseValue, overrideValue);
      continue;
    }

    result[key] = overrideValue;
  }

  return result;
}

function looksLikeCharacterState(value) {
  return (
    isPlainObject(value) &&
    isPlainObject(value.profile) &&
    isPlainObject(value.abilities) &&
    isPlainObject(value.combat) &&
    isPlainObject(value.spellcasting)
  );
}

export function loadPersistedState() {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      return null;
    }

    const parsed = JSON.parse(raw);
    return looksLikeCharacterState(parsed) ? parsed : null;
  } catch (error) {
    console.warn("Не удалось загрузить сохранённое состояние листа", error);
    return null;
  }
}

export function savePersistedState(state) {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch (error) {
    console.warn("Не удалось сохранить состояние листа", error);
  }
}

export function clearPersistedState() {
  try {
    window.localStorage.removeItem(STORAGE_KEY);
  } catch (error) {
    console.warn("Не удалось очистить сохранённое состояние листа", error);
  }
}

export function buildInitialState(baseState) {
  const persistedState = loadPersistedState();
  const baseClone = structuredClone(baseState);

  if (!persistedState) {
    if (Array.isArray(baseClone.skills)) {
      baseClone.skills = normalizeSkills(baseClone.skills);
    }
    return baseClone;
  }

  const merged = deepMerge(baseClone, persistedState);

  if (Array.isArray(merged.skills)) {
    merged.skills = normalizeSkills(merged.skills);
  }

  return merged;
}

const ACTIVE_TAB_STORAGE_KEY = "aurelia-character-sheet:active-tab";

export function initTabs() {
  const tabButtons = document.querySelectorAll("[data-tab]");
  const tabPanels = document.querySelectorAll("[data-panel]");

  const activateTab = (tabId) => {
    tabButtons.forEach((button) => {
      const isActive = button.dataset.tab === tabId;
      button.classList.toggle("is-active", isActive);
      button.setAttribute("aria-selected", String(isActive));
    });

    tabPanels.forEach((panel) => {
      const isActive = panel.dataset.panel === tabId;
      panel.classList.toggle("is-active", isActive);
      panel.hidden = !isActive;
    });

    window.localStorage.setItem(ACTIVE_TAB_STORAGE_KEY, tabId);
  };

  const savedTab = window.localStorage.getItem(ACTIVE_TAB_STORAGE_KEY);
  const initialTab = [...tabButtons].some(
    (button) => button.dataset.tab === savedTab,
  )
    ? savedTab
    : tabButtons[0]?.dataset.tab;

  if (initialTab) {
    activateTab(initialTab);
  }

  tabButtons.forEach((button) => {
    if (button.dataset.bound === "true") {
      return;
    }

    button.addEventListener("click", () => {
      activateTab(button.dataset.tab);
    });

    button.dataset.bound = "true";
  });
}

