        <div class="info-card-title">Деньги</div>
        <div class="currency-grid">
          <label class="currency-field">
            <span>CP</span>
            <input
              class="inventory-input"
              type="number"
              min="0"
              step="1"
              value="${escapeHtml(currency.cp)}"
              data-bind="inventory.currency.cp"
