  wisdom: { key: "wis", short: "WIS", label: "Мудрость" },
  charisma: { key: "cha", short: "CHA", label: "Харизма" },
};

const SKILL_LABELS = {
  athletics: "Атлетика",
  acrobatics: "Акробатика",
  sleightOfHand: "Ловкость рук",
  stealth: "Скрытность",
  arcana: "Магия",
  history: "История",
  investigation: "Расследование",
  nature: "Природа",
  religion: "Религия",
