          data-spell-library-search
          autocomplete="off"
        />
      </label>

      <div class="spell-library-filters" aria-label="Уровень заклинания">
        ${levels.map((level) => {
          const active = String(selectedLevel) === String(level);

          const label = level === "all"
            ? "Все"
            : Number(level) === 0
              ? "Заговоры"
              : `${level}`;

          return `
            <button
              type="button"
              class="spell-filter-chip ${active ? "is-active" : ""}"
              data-spell-library-level="${escapeHtml(level)}"
              aria-pressed="${active ? "true" : "false"}"
            >
              ${escapeHtml(label)}
            </button>
          `;
        }).join("")}
      </div>

      <div class="spell-library-filters" aria-label="Школа магии">
        ${schools.map((school) => {
          const active = schoolFilter === school;

          return `
            <button
              type="button"
              class="spell-filter-chip ${active ? "is-active" : ""}"
              data-spell-library-school="${escapeHtml(school)}"
              aria-pressed="${active ? "true" : "false"}"
            >
              ${escapeHtml(
                school === "all" ? "Все школы" : school,
              )}
            </button>
          `;
        }).join("")}
      </div>

      <div class="spell-library-selection-filters">
        <button
          type="button"
          class="spell-filter-chip ${
            selectionFilter === "selected" ? "is-active" : ""
          }"
          data-spell-library-selection="selected"
          aria-pressed="${
            selectionFilter === "selected" ? "true" : "false"
          }"
        >
          Выбранные
        </button>

        <button
          type="button"
          class="spell-filter-chip ${
            concentrationOnly ? "is-active" : ""
          }"
          data-spell-library-flag="concentrationOnly"
          aria-pressed="${concentrationOnly ? "true" : "false"}"
        >
          Концентрация
        </button>

        <button
          type="button"
          class="spell-filter-chip ${
            ritualOnly ? "is-active" : ""
          }"
          data-spell-library-flag="ritualOnly"
          aria-pressed="${ritualOnly ? "true" : "false"}"
        >
          Ритуал
        </button>

        <button
          type="button"
          class="spell-filter-chip ${
            availableOnly ? "is-active" : ""
          }"
          data-spell-library-flag="availableOnly"
          aria-pressed="${availableOnly ? "true" : "false"}"
        >
          Доступные
        </button>
      </div>
    </div>
  `;
}

function normalizeSearchValue(value) {
  return String(value ?? "")
    .toLocaleLowerCase("ru-RU")
    .replace(/ё/g, "е")
    .trim();
}

function spellMatchesSearch(spell, searchQuery) {
  const query = normalizeSearchValue(searchQuery);

  if (!query) {
    return true;
  }

  const haystack = [
    spell.name,
    spell.originalName,
    spell.school,
    spell.summary,
    spell.description,
  ]
    .map(normalizeSearchValue)
    .join(" ");

  return haystack.includes(query);
}


export function renderSpellLibrary(root, character, derived = null) {
  if (!root) {
    return;
  }


  const sharedSpellStats = {
    spellSaveDc: derived?.spellStats?.spellSaveDc ?? derived?.spellSaveDc ?? null,
    spellcastingModifier:
      derived?.spellStats?.spellcastingModifier ?? null,
    spellAttackBonus:
      derived?.spellStats?.spellAttackBonus ?? derived?.spellAttackBonus ?? null,
    formattedSpellAttackBonus:
      derived?.spellStats?.formattedSpellAttackBonus ??
      derived?.formattedSpellAttackBonus ??
      null,
  };


  const selectedLevel = character?.ui?.spellLibrary?.selectedLevel ?? "all";
  const selectionFilter = character.ui?.spellLibrary?.selectionFilter ?? "all";
  const schoolFilter = character?.ui?.spellLibrary?.schoolFilter ?? "all";
  const searchQuery = character?.ui?.spellLibrary?.searchQuery ?? "";
  const concentrationOnly = Boolean(
    character?.ui?.spellLibrary?.concentrationOnly,
  );
  const ritualOnly = Boolean(
    character?.ui?.spellLibrary?.ritualOnly,
  );
  const availableOnly = Boolean(
    character?.ui?.spellLibrary?.availableOnly,
  );
  const characterLevel = Number(character?.profile?.level ?? 1);
  const expandedSpellIds = Array.isArray(character?.ui?.spellLibrary?.expandedSpellIds)
    ? character.ui.spellLibrary.expandedSpellIds
    : [];


  const allSpells = sortSpells(SPELL_LIBRARY);

  const filteredSpells = allSpells.filter((spell) => {
    const matchesLevel = (
      selectedLevel === "all"
      || String(spell.level) === String(selectedLevel)
    );

    if (!matchesLevel) {
      return false;
    }

    if (
      schoolFilter !== "all"
      && spell.school !== schoolFilter
    ) {
      return false;
    }

    if (concentrationOnly && !spell.concentration) {
      return false;
    }

    if (ritualOnly && !spell.ritual) {
      return false;
    }

    if (
      availableOnly
      && Number(spell.availableFromLevel ?? 1) > characterLevel
    ) {
      return false;
    }

    if (!spellMatchesSearch(spell, searchQuery)) {
      return false;
    }

    if (selectionFilter === "selected") {
      return (
        isCantripSelected(character, spell.id)
        || isPreparedSpellSelected(character, spell.id)
        || isGrantedSpell(character, spell.id)
      );
    }

    return true;
  });


  root.innerHTML = `
    <section class="panel-section">
      ${renderToolbar(character)}
      ${renderSpellLibraryFilters(
        allSpells,
        character,
        {
          selectedLevel,
          selectionFilter,
          schoolFilter,
          searchQuery,
          concentrationOnly,
          ritualOnly,
          availableOnly,
        },
      )}


      <div class="spell-grid spell-grid--library">
        ${
          filteredSpells.length
            ? filteredSpells
                .map((spell) => renderSpellCard(spell, character, expandedSpellIds, sharedSpellStats))
                .join("")
            : `<p class="empty-copy">${
                  selectionFilter === "selected"
                    ? "Нет выбранных заклинаний для текущего фильтра."
                    : "Нет заклинаний для выбранного уровня."
                }</p>`
        }
      </div>
    </section>
  `;
}

import {
  escapeHtml,
  formatSpellLevel,
  renderSpellFacts,
  renderTextParagraph,
  renderSpellBody,
  getBaseSpellFactItems,
  renderSpellCardHeader,
  renderSpellSummaryLine,
  renderSpellCombatStats,
  getSpellGeometryFactItem,
} from "./shared/spell-card.js";
import { buildCharacterSpellCollections } from "../selectors/spellcasting.js";
import {
  formatSpellSave,
  formatSpellDamage,
  formatHealing,
} from "../calculations.js";
import { renderSpellSlotPips } from "./shared/resource-pips.js";



function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function renderSlotEntry(slot) {
  const level = Number(slot?.level || 0);
  const max = Math.max(0, Number(slot?.max || 0));
  const available = clamp(Number(slot?.available || 0), 0, max);

  return `
    <div class="resource-row">
      <div class="resource-row-main">
        <span class="resource-row-title">${escapeHtml(`${level} круг`)}</span>
        <span class="resource-row-meta">${escapeHtml(String(available))}/${escapeHtml(String(max))} доступно</span>
      </div>

      <div class="resource-pip-track">
        ${Array.from({ length: max }, (_, index) => {
          const pipIndex = index + 1;
          const isActive = pipIndex <= available;

          return `
            <button
              type="button"
              class="resource-pip ${isActive ? "resource-pip--active" : ""}"
              data-action="slot-set-used"
              data-slot-level="${escapeHtml(String(level))}"
              data-slot-index="${escapeHtml(String(pipIndex))}"
              aria-label="Установить доступные ячейки ${escapeHtml(String(pipIndex))} из ${escapeHtml(String(max))} для ${escapeHtml(String(level))} круга"
              aria-pressed="${isActive ? "true" : "false"}"
            ></button>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

function formatSigned(value) {
  const number = Number(value);

  if (Number.isNaN(number)) {
    return "—";
  }

  return number >= 0 ? `+${number}` : `${number}`;
}

function renderSpellStats(spell, spellStats = null) {
  const items = [];

  const save = formatSpellSave(spell, spellStats?.spellSaveDc);
  const damage = formatSpellDamage(spell, spellStats?.spellcastingModifier);
  const healing = formatHealing(spell, spellStats?.spellcastingModifier);

  if (save) {
    items.push({ label: "Спасбросок", value: save });
  }

  if (spell.attackBonus) {
    items.push({ label: "Атака", value: spell.attackBonus });
  }

  if (spell.upcast) {
    items.push({ label: "Апкаст", value: spell.upcast });
  }

  if (spell.uses?.max) {
    items.push({
      label: "Использования",
      value: `${spell.uses.current}/${spell.uses.max}${spell.uses.refresh ? ` · ${spell.uses.refresh}` : ""}`,
    });
  }

  if (!items.length) {
    return "";
  }

  return renderSpellFacts(items);
}


function renderSourceBadge(spell) {
  const source = spell.source ?? "class";
  const sourceLabel = spell.sourceLabel ?? "Классовое";

  return `<span class="spell-badge spell-badge--source spell-badge--${escapeHtml(source)}">${escapeHtml(sourceLabel)}</span>`;
}

function renderLevelBadge(spell) {
  return `<span class="spell-badge spell-badge--level">${escapeHtml(formatSpellLevel(spell.level))}</span>`;
}

function renderGrantedBadge() {
  return `<span class="spell-badge spell-badge--granted">Даровано</span>`;
}

function buildSpellBadges(spell, options = {}) {
  const badges = [];

  if (options.showSource !== false) {
    badges.push(renderSourceBadge(spell));
  }

  badges.push(renderLevelBadge(spell));

  if (options.isGranted) {
    badges.push(renderGrantedBadge());
  }

  if (spell.ritual) {
    badges.push(`<span class="spell-badge">Ритуал</span>`);
  }

  if (spell.concentration) {
    badges.push(`<span class="spell-badge">Концентрация</span>`);
  }

  if (spell.availableFromLevel && options.characterLevel && spell.availableFromLevel > options.characterLevel) {
    badges.push(
      `<span class="spell-badge spell-badge--locked">С ${escapeHtml(`${spell.availableFromLevel} уровня`)}</span>`,
    );
  }

  return badges;
}

function getSpellFactItems(spell) {
  const items = [...getBaseSpellFactItems(spell)];

  const geometryItem = getSpellGeometryFactItem(spell);
  if (geometryItem) {
    const hasBaseRange = items.some((item) => item?.label === "Дистанция");
    if (hasBaseRange) {
      const index = items.findIndex((item) => item?.label === "Дистанция");
      items[index] = geometryItem;
    } else {
      items.push(geometryItem);
    }
  }

  if (spell.classes) {
    items.push({
      label: "Классы",
      value: Array.isArray(spell.classes) ? spell.classes.join(", ") : spell.classes,
    });
  }

  return items;
}

function renderSpellCard(spell, spellStats, options = {}) {
  const badges = buildSpellBadges(spell, options);
  const combatStatsHtml = renderSpellCombatStats(spell, spellStats);
  const expandedSpellIds = Array.isArray(options.expandedSpellIds)
    ? options.expandedSpellIds
    : [];

  const isExpanded = expandedSpellIds.includes(spell.id);
  const contentId = `spells-content-${String(spell.id)}`;
  const toggleLabel = isExpanded ? "Свернуть" : "Подробнее";

  return `
    <article class="spell-card ${options.isGranted ? "spell-card--granted" : ""} ${isExpanded ? "spell-card--expanded" : "spell-card--collapsed"}">
      ${renderSpellCardHeader({
        name: spell.name,
        originalName: spell.originalName,
        badges,
      })}

      ${renderSpellSummaryLine(spell)}

      <div class="spell-card-footer">
        <div class="spell-card-footer-actions">
          <button
            type="button"
            class="spell-card-toggle"
            data-spells-toggle="${escapeHtml(spell.id)}"
            aria-expanded="${isExpanded ? "true" : "false"}"
            aria-controls="${contentId}"
          >
            ${toggleLabel}
          </button>
        </div>
      </div>

      <div
        id="${contentId}"
        class="spell-card-expandable"
        ${isExpanded ? "" : "hidden"}
      >
        ${
          isExpanded
            ? `
              ${renderSpellFacts(getSpellFactItems(spell))}
              ${renderSpellStats(spell, spellStats)}
              ${combatStatsHtml}
              ${renderSpellBody(
                renderTextParagraph("spell-description", spell.description ?? spell.summary),
                renderTextParagraph("spell-notes", spell.notes),
                renderTextParagraph("spell-vibe", spell.vibe),
              )}
            `
            : ""
        }
      </div>
    </article>
  `;
}

function renderSpellSection(title, spells, emptyText, options = {}) {
  const cardOptions = options.cardOptions ?? {};
  const spellStats = cardOptions.spellStats ?? null;

  return `
    <section class="panel-section">
      <div class="section-heading-row">
        <div>
          <h2 class="section-title">${escapeHtml(title)}</h2>
          ${
            options.subtitle
              ? `<p class="section-subtitle">${escapeHtml(options.subtitle)}</p>`
              : ""
          }
        </div>
      </div>

      <div class="spell-grid">
        ${
          spells.length
            ? spells
                .map((spell) => renderSpellCard(spell, spellStats, cardOptions))
                .join("")
            : `<p class="empty-copy">${escapeHtml(emptyText)}</p>`
        }
      </div>
    </section>
  `;
}

export function renderSpells(root, character, derived) {
  if (!root) return;

  const spellcasting = character.spellcasting ?? {};
  const level = character.profile?.level ?? 1;
  const spellCollections = buildCharacterSpellCollections(character);

  const expandedSpellIds = Array.isArray(character?.ui?.spells?.expandedSpellIds)
    ? character.ui.spells.expandedSpellIds
    : [];

  const {
    cantrips,
    preparedSpells,
    grantedSpells,
    counts,
    limits,
  } = spellCollections;

  const sharedSpellStats = {
    spellSaveDc: derived?.spellStats?.spellSaveDc ?? derived?.spellSaveDc ?? null,
    spellcastingModifier: derived?.spellStats?.spellcastingModifier ?? null,
    spellAttackBonus: derived?.spellStats?.spellAttackBonus ?? derived?.spellAttackBonus ?? null,
    formattedSpellAttackBonus:
      derived?.spellStats?.formattedSpellAttackBonus ??
      derived?.formattedSpellAttackBonus ??
      null,
  };

  const slotEntries = Array.isArray(derived.spellSlots)
    ? derived.spellSlots.map(renderSpellSlotPips).join("")
    : "";

  root.innerHTML = `
    <section class="panel-section panel-section--spells">
      <div class="section-heading-row">
        <div>
          <h2 class="section-title">Заклинания</h2>
          <p class="section-subtitle">
            Сл спасброска: ${escapeHtml(derived?.spellSaveDc ?? "—")},
            атака заклинанием: ${escapeHtml(formatSigned(derived?.spellAttackBonus ?? 0))}
          </p>
          <p class="section-subtitle">
            Заговоры: ${escapeHtml(counts.cantrips)}/${escapeHtml(limits.cantrips)},
            подготовлено: ${escapeHtml(counts.preparedSpells)}/${escapeHtml(limits.preparedSpells)},
            даровано: ${escapeHtml(counts.grantedSpells)}
          </p>
        </div>
      </div>

      <div class="resource-stack">
        ${slotEntries || `<p class="empty-copy">Нет ячеек заклинаний.</p>`}
      </div>
    </section>

    ${renderSpellSection("Заговоры", cantrips, "Заговоры не выбраны.", {
      subtitle: `${counts.cantrips}/${limits.cantrips}`,
      cardOptions: {
        characterLevel: level,
        showSource: true,
        isGranted: false,
        spellStats: sharedSpellStats,
        expandedSpellIds,
      },
    })}

    ${renderSpellSection("Подготовленные заклинания", preparedSpells, "Подготовленные заклинания отсутствуют.", {
      subtitle: `${counts.preparedSpells}/${limits.preparedSpells}`,
      cardOptions: {
        characterLevel: level,
        showSource: true,
        isGranted: false,
        spellStats: sharedSpellStats,
        expandedSpellIds,
      },
    })}

    ${
      grantedSpells.length
        ? renderSpellSection("Дарованные заклинания", grantedSpells, "Дарованные заклинания отсутствуют.", {
            subtitle: `${counts.grantedSpells}`,
            cardOptions: {
              characterLevel: level,
              showSource: true,
              isGranted: true,
              spellStats: sharedSpellStats,
              expandedSpellIds,
            },
          })
        : ""
    }
  `;
}

import { escapeHtml } from "./spell-card.js";

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

export function renderSpellSlotPips(slot) {
  const level = Number(slot?.level || 0);
  const max = Math.max(0, Number(slot?.max || 0));
  const available = clamp(Number(slot?.available || 0), 0, max);

  return `
    <div class="resource-row">
      <div class="resource-row-main">
        <span class="resource-row-title">${escapeHtml(`${level} круг`)}</span>
        <span class="resource-row-meta">${escapeHtml(String(available))}/${escapeHtml(String(max))} доступно</span>
      </div>

      <div class="resource-pip-track">
        ${Array.from({ length: max }, (_, index) => {
          const pipIndex = index + 1;
          const isActive = pipIndex <= available;

          return `
            <button
              type="button"
              class="resource-pip ${isActive ? "resource-pip--active" : ""}"
              data-action="slot-set-used"
              data-slot-level="${escapeHtml(String(level))}"
              data-slot-index="${escapeHtml(String(pipIndex))}"
              aria-label="Установить доступные ячейки ${escapeHtml(String(pipIndex))} из ${escapeHtml(String(max))} для ${escapeHtml(String(level))} круга"
              aria-pressed="${isActive ? "true" : "false"}"
            ></button>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

import {
  formatSpellSave,
  formatSpellDamage,
  formatHealing
} from '../../calculations.js';

export function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

export function formatSpellLevel(level) {
  return Number(level) === 0 ? "Заговор" : `${level} круг`;
}

export function renderSpellBody(...parts) {
  const content = parts.filter(Boolean).join("");

  if (!content) {
    return "";
  }

  return `<div class="spell-body">${content}</div>`;
}

export function formatSpellSchoolLine(level, school) {
  const levelLabel = formatSpellLevel(level);

  if (!school) {
    return levelLabel;
  }

  return `${levelLabel}, ${school}`;
}

export function getBaseSpellFactItems(spell) {
  return [
    { label: "Время накладывания", value: spell.castTime ?? spell.castingTime },
    { label: "Дистанция", value: spell.range },
    { label: "Компоненты", value: spell.components },
    { label: "Длительность", value: spell.duration },
  ];
}

export function renderSpellFacts(items) {
  const rows = items.filter((item) => item?.label && item?.value);

  if (!rows.length) {
    return "";
  }

  return `
    <dl class="spell-facts">
      ${rows
        .map(
          (item) => `
            <div class="spell-fact">
              <dt class="spell-fact-label">${escapeHtml(item.label)}</dt>
              <dd class="spell-fact-value">${escapeHtml(item.value)}</dd>
            </div>
          `,
        )
        .join("")}
    </dl>
  `;
}

export function renderTextParagraph(className, value) {
  if (!value) {
    return "";
  }

  return `<p class="${className}">${escapeHtml(value)}</p>`;
}

export function renderSpellCardHeader({ name, originalName, badges }) {
  return `
    <div class="spell-card-header">
      <div class="spell-card-heading">
        <h3 class="spell-card-title">${escapeHtml(name)}</h3>
        ${
          originalName
            ? `<div class="spell-card-subtitle">${escapeHtml(originalName)}</div>`
            : ""
        }
      </div>

      <div class="spell-badges">
        ${(badges ?? []).join("")}
      </div>
    </div>
  `;
}

export function renderSpellSummaryLine(spell) {
  return `
    <p class="spell-card-summary">
      ${escapeHtml(formatSpellSchoolLine(spell.level, spell.school))}
    </p>
  `;
}

export function renderSpellQuickFacts(spell) {
  const components = String(spell.components ?? "")
    .split(" (", 1)[0]
    .trim();

  const durationParts = [];

  if (spell.concentration) {
    durationParts.push("Конц.");
  }

  if (spell.ritual) {
    durationParts.push("Ритуал");
  }

  if (spell.duration) {
    durationParts.push(spell.duration);
  }

  const facts = [
    {
      label: "Время",
      value: spell.castTime ?? spell.castingTime,
    },
    {
      label: "Дистанция",
      value: spell.range,
    },
    {
      label: "Компоненты",
      value: components,
    },
    {
      label: "Длительность",
      value: durationParts.join(" · "),
    },
  ].filter((fact) => fact.value);

  return `
    <dl class="spell-quick-facts">
      ${facts
        .map(
          (fact) => `
            <div class="spell-quick-fact">
              <dt>${escapeHtml(fact.label)}</dt>
              <dd>${escapeHtml(fact.value)}</dd>
            </div>
          `,
        )
        .join("")}
    </dl>
  `;
}

export function renderSpellMetaFacts(items, extraClassName = "") {
  const rows = items.filter((item) => item?.label && item?.value);

  if (!rows.length) {
    return "";
  }

  const className = ["spell-facts", extraClassName].filter(Boolean).join(" ");

  return `
    <dl class="${className}">
      ${rows
        .map(
          (item) => `
            <div class="spell-fact">
              <dt class="spell-fact-label">${escapeHtml(item.label)}</dt>
              <dd class="spell-fact-value">${escapeHtml(item.value)}</dd>
            </div>
          `,
        )
        .join("")}
    </dl>
  `;
}

export function renderSpellCombatStats(spell, spellStats = null) {
  const items = [];

  const damage = formatSpellDamage(spell, spellStats?.spellcastingModifier);
  const healing = formatHealing(spell, spellStats?.spellcastingModifier);
  const save = formatSpellSave(spell, spellStats?.spellSaveDc);

  if (damage) {
    items.push({ label: "Урон", value: damage });
  }

  if (healing) {
    items.push({ label: "Лечение", value: healing });
  }

  if (save) {
    items.push({ label: "Спасбросок", value: save });
  }

  return renderSpellMetaFacts(items, "spell-facts--meta spell-facts--combat");
}

export function formatSpellGeometry(spell) {
  if (!spell) {
    return null;
  }

  const parts = [];

  const hasRangeFeet =
    spell.rangeFeet !== null &&
    spell.rangeFeet !== undefined &&
    Number.isFinite(Number(spell.rangeFeet));

  if (hasRangeFeet) {
    const rangeFeet = Number(spell.rangeFeet);

    if (rangeFeet === 0) {
      parts.push("На себя");
    } else {
      parts.push(`${rangeFeet} футов`);
    }
  } else if (spell.range) {
    parts.push(String(spell.range));
  }

  const hasArea =
    spell.areaShape &&
    spell.areaSizeFeet !== null &&
    spell.areaSizeFeet !== undefined &&
    Number.isFinite(Number(spell.areaSizeFeet));

  if (hasArea) {
    const areaSizeFeet = Number(spell.areaSizeFeet);

    const shapeMap = {
      radius: "радиус",
      cube: "куб",
      cone: "конус",
      sphere: "сфера",
      line: "линия",
      cylinder: "цилиндр",
    };

    const shapeLabel = shapeMap[spell.areaShape] ?? spell.areaShape;
    parts.push(`${shapeLabel} ${areaSizeFeet} футов`);
  }

  if (!parts.length) {
    return null;
  }

  return parts.join(" • ");
}

export function getSpellGeometryFactItem(spell) {
  const geometry = formatSpellGeometry(spell);

  if (!geometry) {
    return null;
  }

  return {
    label: "Дистанция / зона",
    value: geometry,
  };
}

import { getBardCantripLimit, getBardPreparedSpellLimit } from "../rules.js";
import {
  SPELL_LIBRARY,
  SPELL_LIBRARY_BY_ID as SPELL_LIBRARY_INDEX,
} from "../../data/spell-library.js";

export const BARD_SPELL_LIBRARY_BY_ID = SPELL_LIBRARY_INDEX;

function uniqueIds(ids) {
  return [...new Set((Array.isArray(ids) ? ids : []).filter(Boolean))];
}

function mergeSpellWithOverrides(baseSpell, override = {}) {
  return {
    ...baseSpell,
    ...override,
  };
}

function resolveSpellById(spellId) {
  if (!spellId) {
    return null;
  }

  return (
    BARD_SPELL_LIBRARY_BY_ID[spellId] ??
    BARD_SPELL_LIBRARY_BY_ID[`${spellId}-2014`] ??
    null
  );
}

function resolveOverrideById(overrides, spellId, resolvedSpell) {
  if (overrides[spellId]) {
    return overrides[spellId];
  }

  if (resolvedSpell?.id && overrides[resolvedSpell.id]) {
    return overrides[resolvedSpell.id];
  }

  return {};
}

function resolveSpellsByIds(spellIds, overrides) {
  return uniqueIds(spellIds)
    .map((spellId) => {
      const baseSpell = resolveSpellById(spellId);

      if (!baseSpell) {
        console.warn("[spellcasting] Unknown spell id:", spellId);
        return null;
      }

      return mergeSpellWithOverrides(
        baseSpell,
        resolveOverrideById(overrides, spellId, baseSpell),
      );
    })
    .filter(Boolean);
}

function sortSpells(spells) {
  return [...spells].sort((left, right) => {
    if (left.level !== right.level) {
      return left.level - right.level;
    }

    return String(left.name).localeCompare(String(right.name), "ru");
  });
}

export function buildCharacterSpellCollections(character) {
  const spellcasting = character?.spellcasting ?? {};
  const level = character?.profile?.level ?? 1;
  const overrides = spellcasting.spellOverrides ?? {};

  const cantripIds = uniqueIds(spellcasting.cantripIds);
  const preparedSpellIds = uniqueIds(spellcasting.preparedSpellIds);
  const grantedSpellIds = uniqueIds(spellcasting.grantedSpellIds);

  const grantedSpellIdSet = new Set(grantedSpellIds);

  const cantrips = sortSpells(
    resolveSpellsByIds(
      cantripIds.filter((id) => !grantedSpellIdSet.has(id)),
      overrides,
    ),
  );

  const preparedSpells = sortSpells(
    resolveSpellsByIds(
      preparedSpellIds.filter((id) => !grantedSpellIdSet.has(id)),
      overrides,
    ),
  );

  const grantedSpells = sortSpells(resolveSpellsByIds(grantedSpellIds, overrides));

  return {
    cantrips,
    preparedSpells,
    grantedSpells,
    counts: {
      cantrips: cantrips.length,
      preparedSpells: preparedSpells.length,
      grantedSpells: grantedSpells.length,
    },
    limits: {
      cantrips: getBardCantripLimit(level),
      preparedSpells: getBardPreparedSpellLimit(level),
    },
  };
}

function isSpellIdSelected(selectedIds, spellId) {
  const canonicalTarget = resolveSpellById(spellId)?.id ?? spellId;

  return uniqueIds(selectedIds).some((id) => {
    if (id === spellId || id === canonicalTarget) {
      return true;
    }

    return resolveSpellById(id)?.id === canonicalTarget;
  });
}

export function isCantripSelected(character, spellId) {
  return isSpellIdSelected(character?.spellcasting?.cantripIds, spellId);
}

export function isPreparedSpellSelected(character, spellId) {
  return isSpellIdSelected(character?.spellcasting?.preparedSpellIds, spellId);
}

export function isGrantedSpell(character, spellId) {
  return isSpellIdSelected(character?.spellcasting?.grantedSpellIds, spellId);
}

export function findMissingSpellIds(character) {
  const spellcasting = character?.spellcasting ?? {};
  const allIds = [
    ...uniqueIds(spellcasting.cantripIds),
    ...uniqueIds(spellcasting.preparedSpellIds),
    ...uniqueIds(spellcasting.grantedSpellIds),
  ];

  return allIds.filter((spellId) => !resolveSpellById(spellId));
}
